import pyomo.environ as pyo

DATA = {
    "supplements": ["A", "B"],
    "cost": {"A": 14, "B": 25},
    "calcium": {"A": 30, "B": 60},
    "magnesium": {"A": 50, "B": 10},
    "calcium_required": 400,
    "magnesium_required": 50,
}

GOLD_ANSWER = None


def build_model(data=None):
    d = data or DATA
    model = pyo.ConcreteModel()

    # Sets
    model.S = pyo.Set(initialize=d["supplements"])
    model.N = pyo.Set(initialize=["calcium", "magnesium"])

    # Decision variables: servings of each supplement (continuous, >= 0)
    def x_bounds(m, s):
        return (0, None)
    model.x = pyo.Var(model.S, domain=pyo.NonNegativeReals, bounds=x_bounds)

    # Objective: minimise daily cost
    def cost_rule(m):
        return sum(d["cost"][s] * m.x[s] for s in m.S)
    model.obj = pyo.Objective(rule=cost_rule, sense=pyo.minimize)

    # Content parameter helper
    content = {
        "calcium": d["calcium"],
        "magnesium": d["magnesium"],
    }
    required = {
        "calcium": d["calcium_required"],
        "magnesium": d["magnesium_required"],
    }

    # Constraint: each nutrient must meet its daily requirement (at least)
    def nutrient_rule(m, n):
        return sum(content[n][s] * m.x[s] for s in m.S) >= required[n]
    model.nutrient = pyo.Constraint(model.N, rule=nutrient_rule)

    return model
